/** Built by the `baja-match-data` plugin in vite.config.ts. Typed in ./match.ts. */
declare module 'virtual:match-data' {
  export const matchId: string;
  export const events: unknown[];
  export const overlays: unknown[];
  export const playEvents: unknown[];
  export const teams: unknown;
  /** Illustrative positions file, fetched when drawn; null when the match has none. */
  export const positionsUrl: string | null;
}
